WITH inner_cte AS ( SELECT sd.DEPARTMENT_NAME, AVG(tso.NUM_ENROLLED_STUDENTS) AS avg_enrolled FROM TIP_SUBJECT_OFFERED tso JOIN SIS_DEPARTMENT sd ON tso.OFFER_DEPT_CODE = sd.DEPARTMENT_CODE WHERE tso.TERM_CODE = '2022FA' AND sd.IS_DEGREE_GRANTING = 'Y' AND sd.DEPARTMENT_CODE <> '6' GROUP BY sd.DEPARTMENT_NAME ) SELECT DEPARTMENT_NAME, avg_enrolled FROM inner_cte WHERE avg_enrolled > ( SELECT AVG(tso.NUM_ENROLLED_STUDENTS) FROM TIP_SUBJECT_OFFERED tso JOIN SIS_DEPARTMENT sd ON tso.OFFER_DEPT_CODE = sd.DEPARTMENT_CODE WHERE tso.TERM_CODE = '2022FA' AND sd.IS_DEGREE_GRANTING = 'Y' AND sd.DEPARTMENT_CODE <> '6' ) ORDER BY DEPARTMENT_NAME;